/**
 * The payload must match the platform's reference exam `grade5-math-unit1` exactly:
 * same top-level field names/types, same summary/lesson/detail shapes, same status
 * labels, same gradeLabel scale and the same delivery constants. The fixture was
 * generated by running the reference exam's OWN functions (see check-reference.mjs).
 */
import { describe, expect, it } from "vitest";
import { EXAM_ID, EXAM_TITLE, SHEETS_TOKEN, SHEETS_URL } from "../src/config";
import { QUESTIONS, TOTAL_MARKS } from "../src/data/questions";
import { gradeExam } from "../src/logic/grading";
import { buildReport } from "../src/logic/report";
import {
  ATTEMPT_TIMEOUT_MS, MAX_ATTEMPTS, PENDING_PREFIX, RETRY_DELAYS_MS, STATUS_AR,
  buildPayload, gradeLabel, newAttemptId, pendingKey,
  type SubmissionPayload,
} from "../src/logic/submit";
import type { AnswerMap } from "../src/types";
import { fixture, shapeOf } from "./helpers";

const contract = fixture("grade5-contract.json");
const golden = fixture("grading-golden.json");
const ATTEMPT = "8f1c2d34-1a2b-4c3d-9e4f-5a6b7c8d9e0f";
const START = 1_700_000_000_000;
const SUBMIT = START + 1_234_000;

function mixedPayload(): { payload: SubmissionPayload; result: ReturnType<typeof gradeExam>; report: string } {
  const answers = golden.mixed.answers as AnswerMap;
  const result = gradeExam(answers, "Baseline Student", START, SUBMIT);
  const report = buildReport(result);
  return { payload: buildPayload({ attemptId: ATTEMPT, result, answers, reportText: report }), result, report };
}

describe("3. payload structure == grade5-math-unit1 contract", () => {
  it("URL, token and delivery constants are the reference ones (no Apps Script changes)", () => {
    expect(SHEETS_URL).toBe(contract.url);
    expect(SHEETS_TOKEN).toBe(contract.token);
    expect(MAX_ATTEMPTS).toBe(contract.delivery.maxAttempts);
    expect(Array.from(RETRY_DELAYS_MS)).toEqual(contract.delivery.retryDelaysMs);
    expect(ATTEMPT_TIMEOUT_MS).toBe(contract.delivery.attemptTimeoutMs);
    expect(PENDING_PREFIX).toBe(`pending:${EXAM_ID}:`);
    expect(pendingKey(ATTEMPT)).toBe(`pending:${EXAM_ID}:${ATTEMPT}`);
    expect(contract.delivery.pendingKeyPattern).toBe("pending:<EXAM_ID>:<attemptId>");
  });

  it("EXAM_ID is unique, equals the folder, and the examTitle is the official index title", () => {
    expect(EXAM_ID).toBe("grade4-english-curriculum-l1-l5");
    expect(EXAM_ID).not.toBe(contract.referenceExamId);
    expect(EXAM_TITLE).toBe("Curriculum Test Lessons 1 to 5");
  });

  it("top-level, summary, lesson and detail field names/types are identical", () => {
    const { payload } = mixedPayload();
    expect(Object.keys(payload).sort()).toEqual(Object.keys(contract.payload).sort());
    expect(shapeOf(payload)).toEqual(contract.payload);
    expect(shapeOf(payload.summary)).toEqual(contract.summary);
    expect(payload.lessons).toHaveLength(5);
    expect(shapeOf(payload.lessons[0])).toEqual(contract.lesson);
    expect(shapeOf(payload.details[0])).toEqual(contract.detail);
  });

  it("status labels and the gradeLabel scale are the reference ones", () => {
    expect(STATUS_AR).toEqual(contract.statuses);
    for (const [p, label] of Object.entries(contract.gradeLabels)) {
      expect(gradeLabel(Number(p))).toBe(label);
    }
  });

  it("all numbers come from the same graded result the student sees", () => {
    const { payload, result, report } = mixedPayload();
    expect(payload.token).toBe(SHEETS_TOKEN);
    expect(payload.attemptId).toBe(ATTEMPT);
    expect(payload.examId).toBe(EXAM_ID);
    expect(payload.examTitle).toBe(EXAM_TITLE);
    expect(payload.studentName).toBe(result.studentName);
    expect(payload.startAt).toBe(new Date(result.startedAt).toISOString());
    expect(payload.submitAt).toBe(new Date(result.submittedAt).toISOString());
    expect(payload.elapsedSec).toBe(Math.max(0, Math.floor(result.durationMs / 1000)));

    expect(payload.summary).toEqual({
      total: result.totalEarned,
      max: TOTAL_MARKS,
      percentage: result.percentage,
      gradeLabel: gradeLabel(result.percentage),
      fullQuestions: result.correctQuestions,
      partialQuestions: result.partiallyCorrect,
      wrongQuestions: result.incorrectQuestions,
      correctSubparts: payload.details.filter((d) => d.status === STATUS_AR.correct).length,
      partialSubparts: payload.details.filter((d) => d.status === STATUS_AR.partial).length,
      wrongSubparts: payload.details.filter((d) => d.status === STATUS_AR.wrong).length,
      unansweredSubparts: payload.details.filter((d) => d.status === STATUS_AR.unanswered).length,
    });

    const totalParts = QUESTIONS.reduce((s, q) => s + q.parts.length, 0);
    expect(payload.details).toHaveLength(totalParts);
    expect(payload.details.reduce((s, d) => s + d.awarded, 0)).toBe(result.totalEarned);
    expect(payload.details.reduce((s, d) => s + d.marks, 0)).toBe(100);
    expect(payload.lessons.reduce((s, l) => s + l.max, 0)).toBe(100);
    expect(payload.lessons.reduce((s, l) => s + l.awarded, 0)).toBe(result.totalEarned);
    expect(payload.reportText).toBe(report);
    expect(report).toContain("OFFICIAL EXAM REPORT");
  });

  it("a blank part is reported as unanswered with the reference label", () => {
    const { payload } = mixedPayload();
    const blank = payload.details.find((d) => d.label === "q23d");
    expect(blank?.status).toBe(contract.statuses.unanswered);
    expect(blank?.awarded).toBe(0);
  });

  it("attempt ids are unique", () => {
    const ids = new Set(Array.from({ length: 500 }, () => newAttemptId()));
    expect(ids.size).toBe(500);
  });
});
